#define S(a, b, c) smoothstep(a, b, c)
precision highp float;


const float M_PI = 3.14159265358979323846264338327950288;

float rad(float deg) {
    return deg/180.0*M_PI;
}

vec3 rotate(vec3 p, vec3 rt) {
    float cx = cos(rt.x);
    float sx = sin(rt.x);
    mat3 rx = mat3(1.0, 0.0, 0.0,
                   0.0, cx,  -sx,
                   0.0, sx,  cx);
    float cy = cos(rt.y);
    float sy = sin(rt.y);
    mat3 ry = mat3(cy,  0.0, sy,
                   0.0, 1.0, 0.0,
                   -sy, 0.0, cy );
    float cz = cos(rt.z);
    float sz = sin(rt.z);
    mat3 rz = mat3(cz,  -sz, 0.0,
                   sz,  cz,  0.0,
                   0.0, 0.0, 1.0);
    p *= rx;
    p *= ry;
    p *= rz;
    return p;
}

vec3 uvToForwardVector(vec2 uv, vec3 camRot) {
    float FOV = rad(30.0);
    float sz = tan(FOV);
    vec3 camDir = vec3(1.0, sz*uv.x, sz*uv.y);
    camDir = normalize(camDir);
    vec3 rot = vec3(0.0, camRot.y, camRot.z);
    return normalize(rotate(camDir, rot));
}


int getDirectionCode(float v) {
    return int(hash(uint(int(floor(v*100.0)))));
}

vec3 getDirectionCodeCenter(vec3 r) {
   return r + (vec3(0.5) - fract(r*100.0))/100.0; // -> 100r from 0 to 1, want 0.5
}

float StarThreshold = 0.07;

vec3 skybox(vec3 ray) {
    float val = randS(uint(getDirectionCode(ray.x)^getDirectionCode(ray.y)^getDirectionCode(ray.z)));
    if (val > StarThreshold) return vec3(0.0);
    float d = length(ray - getDirectionCodeCenter(ray));
    return vec3(S(0.00003*val, 0.0, d*d));
    return vec3(0.0);
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord-iResolution.xy*.5)/iResolution.y;

    vec3 cam = texelFetch(iChannel0, ivec2(0, 0), 0).xyz*1000.0;

    vec3 srot = (texelFetch(iChannel0, ivec2(1, 0), 0).xyz);
    srot *= 360.0;
    srot = vec3(rad(srot.x), rad(srot.y), rad(srot.z));    
    vec3 ray = uvToForwardVector(uv, srot);



    // Time varying pixel color
    vec3 col = skybox(ray);

    // Output to screen
    fragColor = vec4(col,1.0);
}

const ivec2 FS_ADDR = ivec2(0.0);

const vec4 fs_stt = vec4(1.0);

uint seed = 0u;

void setSeed(uint s) {
    seed = s;
}

uint hash(uint s) {
    s ^= 2747636419u;
    s *= 2654435769u;
    s ^= s >> 16;
    s *= 2654435769u;
    s ^= s >> 16;
    s *= 2654435769u;
    return s;
}

uint randI() {
    seed = hash(seed);
    return seed;
}

float randS(uint s) {
    uint rn = hash(s);
    rn %= 1000000000u;
    float rs = float(rn);
    rs /= 1000000000.0;
    return rs;
}

float rand() {
    uint rn = randI();
    rn %= 1000000000u;
    float rs = float(rn);
    rs /= 1000000000.0;
    return rs;
}

#define setNSeed() setSeed(uint(iResolution.x*fragCoord.y+fragCoord.x + float(hash(uint(iTime*1000.0))%1000u)))

//Key code viewer: https://www.shadertoy.com/view/4tt3Wn

const int W = 87;
const int A = 65;
const int S = 83;
const int D = 68;

const int UP = 38;
const int DOWN = 40;
const int RIGHT = 39;
const int LEFT = 37;

const float M_PI = 3.14159265358979323846264338327950288;

vec3 rad(vec3 deg) {
    return deg/180.0*M_PI;
}

vec3 rotate(vec3 p, vec3 rt) {
    float cx = cos(rt.x);
    float sx = sin(rt.x);
    mat3 rx = mat3(1.0, 0.0, 0.0,
                   0.0, cx,  -sx,
                   0.0, sx,  cx);
    float cy = cos(rt.y);
    float sy = sin(rt.y);
    mat3 ry = mat3(cy,  0.0, sy,
                   0.0, 1.0, 0.0,
                   -sy, 0.0, cy );
    float cz = cos(rt.z);
    float sz = sin(rt.z);
    mat3 rz = mat3(cz,  -sz, 0.0,
                   sz,  cz,  0.0,
                   0.0, 0.0, 1.0);
    p *= rx;
    p *= ry;
    p *= rz;
    return p;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec3 rot = texelFetch(iChannel0, ivec2(1, 0), 0).xyz;
    float rots = .2;
    if (length(fragCoord-fract(fragCoord.xy)-vec2(0.0, 0.0))<0.1) {
        float speed = 5.0;
        vec3 pos = texelFetch(iChannel0, ivec2(0, 0), 0).xyz*1000.0;
        vec3 forward = vec3(1.0, 0.0, 0.0);
        forward = rotate(forward, rad(rot*360.0));
        vec3 right = vec3(0.0, 1.0, 0.0);
        right = rotate(right, rad(rot*360.0));
        if (texelFetch(iChannel1, ivec2(W, 0), 0).x > 0.5) {
            pos += forward * speed * iTimeDelta;
        } else if (texelFetch(iChannel1, ivec2(S, 0), 0).x > 0.5) {
            pos += -forward * speed * iTimeDelta;
        } else if (texelFetch(iChannel1, ivec2(A, 0), 0).x > 0.5) {
            pos += -right * speed * iTimeDelta;
        } else if (texelFetch(iChannel1, ivec2(D, 0), 0).x > 0.5) {
            pos += right * speed * iTimeDelta;
        } 
        fragColor = vec4(pos/1000.0, 1.0);
    } else if (length(fragCoord-fract(fragCoord.xy)-vec2(1.0, 0.0))<0.1) {
        if (texelFetch(iChannel1, ivec2(UP, 0), 0).x > 0.5) {
            rot.y += -iTimeDelta * rots;
        } else if (texelFetch(iChannel1, ivec2(DOWN, 0), 0).x > 0.5) {
            rot.y += iTimeDelta * rots;
        } else if (texelFetch(iChannel1, ivec2(RIGHT, 0), 0).x > 0.5) {
            rot.z += iTimeDelta * rots;
        } else if (texelFetch(iChannel1, ivec2(LEFT, 0), 0).x > 0.5) {
            rot.z += -iTimeDelta * rots;
        }
        rot = fract(rot);
        fragColor = vec4(rot, 1.0);
    } else {
        fragColor = vec4(0.0,0.0,0.0,1.0);
    }
}
